TLM.f("Sancti/07-20",{"officium":"S. Hieronymi Emiliani Confessoris","rule":["vide C5","Gloria"],"fallback":"Commune/C5","from":{"Tractus":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Thren 2:11"},{"k":"text","la":"Effúsum est in terra jecur meum super contritióne fíliæ pópuli mei, cum defíceret párvulus et lactens in platéis óppidi."},{"k":"ref","la":"Ps 112:1"},{"k":"text","la":"Laudáte, pueri, Dóminum: laudáte nomen Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Effúsum est in terra jecur meum super contritióne fíliæ pópuli mei, cum defíceret párvulus et lactens in platéis óppidi."}],"Oratio":[{"k":"text","la":"Deus, misericordiárum pater, per mérita et intercessiónem beáti Hieronymi, quem órphanis adjutorem et patrem esse voluísti: concéde; ut spíritum adoptiónis, quo fílii tui nominámur et sumus, fidéliter custodiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 58:7-11"},{"k":"text","la":"Hæc dicit Dóminus: Frange esuriénti panem tuum, et egénos vagósque induc in domum tuam: cum víderis nudum, operi eum, et carnem tuam ne despéxeris. Tunc erúmpet quasi mane lumen tuum, et sánitas tua citius oriétur, et anteíbit fáciem tuam justítia tua, et glória Dómini cólliget te. Tunc invocábis, et Dóminus exáudiet: clamabis, et dicet: Ecce, adsum; si abstúleris de médio tui caténam, et desíeris exténdere dígitum, et loqui quod non prodest. Cum effúderis esuriénti ánimam tuam, et ánimam afflíctam repléveris. Oriétur in tenebris lux tua, et ténebræ tuæ erunt sicut merídies. Et réquiem tibi dabit Dóminus semper, et implébit splendóribus ánimam tuam, et ossa tua liberábit, et eris quasi hortus irríguus, et sicut fons aquárum, cujus non defícient aquæ."}],"Graduale":[{"k":"rubric","la":"Prov 5:16"},{"k":"text","la":"Derivéntur fontes tui foras, et in platéis aquas tuas divide."},{"k":"ref","la":"Ps 111:5-6"},{"k":"text","la":"Jucúndus homo, qui miserétur et cómmodat: dispónet sermónes suos in judício, quia in ætérnum non commovébitur. Allelúja, allelúja."},{"k":"ref","la":"Ps 111:9"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum, in mandátis ejus cupit nimis. Allelúja."},{"k":"text","la":"Ibid., 9, 3","mark":"V"},{"k":"text","la":"Dispérsit, dedit paupéribus: justítia ejus manet in sǽculum sǽculi. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 91:13; 91:14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur in domo Dómini."},{"k":"ref","la":"Ps 91:3"},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem."},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:13-21"},{"k":"text","la":"In illo témpore: Obláti sunt Jesu párvuli, ut manus eis impóneret et oráret. Discípuli autem increpábant eos. Jesus vero ait eis: Sínite párvulos, et nolíte eos prohibére ad me veníre: tálium est enim regnum cœlórum. Et cum imposuísset eis manus, ábiit inde. Et ecce, unus accedens, ait illi: Magíster bone, quid boni fáciam, ut hábeam vitam ætérnam? Qui dixit ei: Quid me intérrogas de bono? Unus est bonus, Deus. Si autem vis ad vitam íngredi, serva mandáta. Dicit illi: Quæ? Jesus autem dixit: Non homicídium fácies: Non adulterábis: Non fácies furtum: Non falsum testimónium dices: Hónora patrem tuum et matrem tuam, et díliges próximum tuum sicut te ipsum. Dicit illi adoléscens: Omnia hæc custodívi a juventúte mea: quid adhuc mihi deest? Ait illi Jesus: Si vis perféctus esse, vade, vende, quæ habes, et da paupéribus, et habébis thesáurum in cœlo: et veni, séquere me."}],"Offertorium":[{"k":"ref","la":"Tob 12:12"},{"k":"text","la":"Quando orábas cum lácrimis, et sepeliébas mórtuos, et derelinquébas prándium tuum, et mórtuos abscondébas per diem in domo tua, et nocte sepeliébas eos: ego óbtuli oratiónem tuam Dómino."}],"Secreta":[{"k":"text","la":"Clementíssime Deus, qui, véteri homine consúmpto, novum secúndum te in beáto Hierónymo creáre dignátus es: da, per mérita ipsíus; ut nos, páriter renováti, hanc placatiónis hóstiam in odórem tibi suavíssimum offerámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Jac 1:27"},{"k":"text","la":"Relígio munda et immaculáta apud Deum et Patrem hæc est: Visitáre pupíllos et víduas in tribulatióne eórum, et immaculátum se custodíre ab hoc sǽculo."}],"Postcommunio":[{"k":"text","la":"Angelórum pane refécti te, Dómine, supplíciter deprecámur: ut, qui ánnuam beáti Hierónymi Confessóris tui memóriam celebráre gaudémus; ejúsdem étiam et exémplum imitémur, et amplíssimum in regno tuo præmium obtinére valeámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"94eb7a24c8d08873":{"t":"Tuž 2, 11, Ps 112, 1\n(Tuž 2, 11) Sav mi je život ogorčen radi žalosti kćeri naroda mojega, jer djeca i dojenčad ginu na gradskim ulicama. (Ps 112, 1) Hvalite, djeco, Gospodina, hvalite ime Gospodnje.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Tuž 2, 11) Sav mi je život ogorčen radi žalosti kćeri naroda mojega, jer djeca i dojenčad ginu na gradskim ulicama.","v":"tren ps → ∅; tren → ∅"},"bc94b3d8ade264a1":{"t":"<i>Pomolimo se</i>.\nBože, oče milosrđa, daj da po zaslugama i zagovoru blaženoga Jeronima, koji je po tvojoj volji bio pomoćnik i otac siročadi, vjerno čuvamo duh posinaštva po kojem se tvojom djecom nazivamo i jesmo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c047c67e7b224481":{"t":"Iz 58, 7-11\nČitanje Izaije proroka. Ovo govori Gospodin: Lomi gladnome svoj kruh, siromasima i putnicima daj konak pod svojim krovom, zaodjeni gola, ne prezri svoga brata. Tada će tvoje svjetlo sinuti kao zora, brzo će ti se povratiti zdravlje. Tvoja će pravda ići pred tobom i obujmit će te Gospodnja slava. Zazivat ćeš, i Gospodin će uslišati, vapit ćeš, i odgovorit će: Evo me. Ako zbaciš sa sebe okove, prestaneš pružati prst i govoriti zlo, pa otvoriš svojeg srce gladnome i nasitiš nevoljnika, zasjat će i u mraku tvoje svjetlo, nestat će tame i bit će kao podne. Gospodin će ti osigurati trajan mir, prosvijetlit će ti dušu i okrijepiti tvoje kosti, bit ćeš kao natopljen vrt i kao izvor kojemu ne ponestaje vode."},"582079aabb575c75":{"t":"Izr 5, 16, Ps 111, 5-6\n(Izr 5, 16) Neka se tvoji izvori razlijevaju vani i tvoja voda na trgovima. (Ps 111, 5-6) Ugodan je čovjek koji je milostiv i darežljiv, njegove su riječi odmjerene, neće nikada posrnuti.\n\nPs 111, 9\n<i>Aleluja</i>, <i>aleluja</i>.\nObilno je dijelio i davao siromasima, darežljivost njegova ostaje dovijeka. <i>Aleluja</i>."},"a823a10351fa97cc":{"t":"Mt 19, 13-21\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme donosili su Isusu djecu daj stavi ruke na njih i da se pomoli. Učenici su ih korili, a Isus reče: Pustite djecu i ne zabranjujte im dolaziti meni, jer takovima pripada kraljevstvo nebesko. I stavivši na njih ruke otiđe odanle. I gle. netko pristupi i reče mu: Dobri učitelju, kakvo dobro da učinim da imam život vječni? On mu odgovori: Što me pitaš za dobro? Jedan je dobar, Bog. A ako hoćeš da uđeš u život, vrši zapovijedi. Upita ga: Koje? Isus odgovori: Ne ubij, ne čini preljube, ne ukradi, ne reci lažna svjedočanstva, poštuj oca i mater i ljubi bližnjega svoga kao samoga sebe. Reče mu mladić: Sve sam to vršio od svoje mladosti. Sto mi još nedostaje? Isus mu odgovori: Ako hoćeš biti savršen, idi prodaj svoju imovinu i daj siromasima i imat ćeš blago na nebu. Dođi i idi za mnom."},"b345864e0597c6c4":{"t":"Tob 12, 12\nDok si sa suzama molio i sahranjivao mrtve, dok si ostavljao svoju hranu i mrtvace danju sakrivao u svojoj kući, a noću ih pokopavao, ja sam prikazivao tvoju molitvu Gospodinu."},"0efcc957663a6371":{"t":"Preblagi Bože, koji si se udostojao u blaženom Jeronimu promijeniti starog čovjeka u novoga po tvom uzoru, daj da po njegovim zaslugama i mi isto tako obnovljeni prikazujemo ovu pomirbenu žrtvu na tebi preugodan miris.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"a3d87956cc758cd2":{"t":"Jak 1, 27\nPravo i neokaljano bogoštovlje pred Bogom Ocem je ovo: Zauzeti se za sirote i udovice u njihovoj nevolji i čuvati sebe čista od ovoga svijeta."},"801d107dc883ee07":{"t":"<i>Pomolimo se</i>.\nOkrijepljeni anđeoskim kruhom ponizno te molimo, Gospodine, da mi koji se radujemo što slavimo godišnji spomen blaženoga Jeronima priznavaoca tvoga, uzmognemo nasljedovati njegov primjer i zadobiti bogatu nagradu u tvome kraljevstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
